from itertools import combinations

def get_grid_edges(m, n):
    edges = []
    for i in range(m):
        for j in range(n):
            v = i * n + j
            if j + 1 < n:
                edges.append((v, v + 1))
            if i + 1 < m:
                edges.append((v, v + n))
    return edges

def perfect_matchings(m, n):
    total = m * n
    if total % 2 != 0:
        return []
    edges = get_grid_edges(m, n)
    adj = [[] for _ in range(total)]
    for e in edges:
        adj[e[0]].append(e[1])
        adj[e[1]].append(e[0])

    matchings = []
    def backtrack(used, matching):
        v = -1
        for i in range(total):
            if not used[i]:
                v = i
                break
        if v == -1:
            matchings.append(frozenset(matching))
            return
        used[v] = True
        for u in adj[v]:
            if not used[u]:
                used[u] = True
                matching.add((min(v,u), max(v,u)))
                backtrack(used, matching)
                matching.discard((min(v,u), max(v,u)))
                used[u] = False
        used[v] = False

    backtrack([False]*total, set())
    return matchings

def find_alternating_4cycles(m, n, matching):
    """Find all M-alternating 4-cycles (unit squares with 2 matching edges alternating)."""
    matching_set = set(matching)
    alt_squares = []
    for i in range(m - 1):
        for j in range(n - 1):
            v00 = i * n + j
            v01 = i * n + j + 1
            v10 = (i + 1) * n + j
            v11 = (i + 1) * n + j + 1
            # Edges of the square: (v00,v01), (v10,v11) horizontal; (v00,v10), (v01,v11) vertical
            h1 = (min(v00,v01), max(v00,v01))
            h2 = (min(v10,v11), max(v10,v11))
            v1 = (min(v00,v10), max(v00,v10))
            v2 = (min(v01,v11), max(v01,v11))
            # Alternating: both horizontal in matching, or both vertical in matching
            if h1 in matching_set and h2 in matching_set:
                alt_squares.append((i, j, 'H'))  # flip to vertical
            elif v1 in matching_set and v2 in matching_set:
                alt_squares.append((i, j, 'V'))  # flip to horizontal
    return alt_squares

def max_disjoint_alt_cycles(m, n, alt_squares):
    """Find maximum number of disjoint alternating 4-cycles.
    Two 4-cycles are disjoint if they share no vertex."""
    # Each square (i,j) covers vertices: (i,j), (i,j+1), (i+1,j), (i+1,j+1)
    # Find maximum independent set of squares (no shared vertices)
    # This is a maximum independent set problem on a graph where squares are nodes
    # and edges connect squares that share a vertex.

    squares = alt_squares
    if not squares:
        return 0

    # Build conflict graph
    def square_vertices(sq):
        i, j, _ = sq
        return {i * n + j, i * n + j + 1, (i+1) * n + j, (i+1) * n + j + 1}

    k = len(squares)
    conflicts = set()
    for a in range(k):
        for b in range(a + 1, k):
            if square_vertices(squares[a]) & square_vertices(squares[b]):
                conflicts.add((a, b))

    # Find maximum independent set (brute force for small k)
    best = 0
    for size in range(k, 0, -1):
        found = False
        for subset in combinations(range(k), size):
            valid = True
            for a in range(len(subset)):
                for b in range(a + 1, len(subset)):
                    if (subset[a], subset[b]) in conflicts:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                best = size
                found = True
                break
        if found:
            break
    return best

# Compute for n=1,2,3
for n in range(1, 4):
    m = 2 * n
    matchings = perfect_matchings(m, m)
    print(f"n={n}, grid {m}x{m}, {len(matchings)} matchings")

    min_anti_forcing = float('inf')
    worst_matching = None

    for mat in matchings:
        alt_squares = find_alternating_4cycles(m, m, mat)
        max_disjoint = max_disjoint_alt_cycles(m, m, alt_squares)
        if max_disjoint < min_anti_forcing:
            min_anti_forcing = max_disjoint
            worst_matching = mat

    print(f"  Min anti-forcing number (from 4-cycles only): {min_anti_forcing}")
    print(f"  Worst matching: {worst_matching}")
    print(f"  Expected: 2n-1 = {2*n - 1}")
    print()

